  std::any parseTrade(std::any trade, std::any market = std::any{}) override {
    //
    // fetchTrades
    //         {
    //                 "timestamp":1644651458,
    //                 "price":"1180785.00000000",
    //                 "amount":"0.00020000",
    //                 "isBuyer":false
    //         }
    //
    // fetchMyTrades
    //         {
    //                 "tradeId":"5685030251",
    //                 "orderId":"9669168142",
    //                 "price":"11821.8",
    //                 "action":"SELL",
    //                 "baseAmount":"0.01",
    //                 "quoteAmount":"118.218",
    //                 "fee":"0.236436",
    //                 "feeSymbol":"BNB",
    //                 "isTaker":true,
    //                 "timestamp":1644905714862,
    //                 "createdTimestamp":1644905714862
    //         }
    //
    std::any id = this->safeString(trade, std::string("tradeId"));
    std::any orderId = this->safeString(trade, std::string("orderId"));
    std::any timestamp = std::any{};
    if (isTrue(isEqual(id, std::any{}))) {
      timestamp = this->safeTimestamp(trade, std::string("timestamp"));
    } else {
      timestamp = this->safeInteger(trade, std::string("timestamp"));
    }
    std::any marketId = this->safeString(trade, std::string("pair"));
    market = this->safeMarket(marketId, market);
    std::any symbol = this->safeString(market, std::string("symbol"));
    std::any price = this->safeString(trade, std::string("price"));
    std::any type = this->safeStringLower(trade, std::string("type"));
    std::any side = this->safeStringLower(trade, std::string("action"));
    if (isTrue(isEqual(side, std::any{}))) {
      std::any isBuyer = this->safeBool(trade, std::string("isBuyer"));
      if (isTrue(isEqual(isBuyer, true))) {
        side = std::string("buy");
      } else {
        side = std::string("sell");
      }
    }
    std::any amount = this->safeString(trade, std::string("amount"));
    if (isTrue(isEqual(amount, std::any{}))) {
      amount = this->safeString(trade, std::string("baseAmount"));
    }
    std::any fee = std::any{};
    std::any feeAmount = this->safeString(trade, std::string("fee"));
    std::any feeSymbol = this->safeCurrencyCode(
        this->safeString(trade, std::string("feeSymbol")));
    if (isTrue(!isEqual(feeAmount, std::any{}))) {
      fee = ccxt::dict{
          {std::string("cost"), feeAmount},
          {std::string("currency"), feeSymbol},
          {std::string("rate"), std::any{}},
      };
    }
    std::any isTaker = this->safeBool(trade, std::string("isTaker"));
    std::any takerOrMaker = std::any{};
    if (isTrue(!isEqual(isTaker, std::any{}))) {
      if (isTrue(isTaker)) {
        takerOrMaker = std::string("taker");
      } else {
        takerOrMaker = std::string("maker");
      }
    }
    return this->safeTrade(
        ccxt::dict{
            {std::string("id"), id},
            {std::string("info"), trade},
            {std::string("order"), orderId},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("symbol"), symbol},
            {std::string("takerOrMaker"), takerOrMaker},
            {std::string("type"), type},
            {std::string("side"), side},
            {std::string("price"), price},
            {std::string("amount"), amount},
            {std::string("cost"), std::any{}},
            {std::string("fee"), fee},
        },
        market);
  }

