  /**
   * @method
   * @name bitopro#fetchMyTrades
   * @description fetch all trades made by the user
   * @see
   * https://github.com/bitoex/bitopro-offical-api-docs/blob/master/api/v3/private/get_trades_data.md
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch trades for
   * @param {int} [limit] the maximum number of trades structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=trade-structure}
   */
  std::shared_future<std::any>
  fetchMyTrades(std::any symbol = std::any{}, std::any since = std::any{},
                std::any limit = std::any{},
                std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(
                           " fetchMyTrades() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("pair"),
                      ::getValue(market, std::string("id"))},
                 };
                 std::any response =
                     awaitValue(this->privateGetOrdersTradesPair(
                         this->extend(request, params)));
                 std::any trades = this->safeList(response, std::string("data"),
                                                  ccxt::list{});
                 //
                 //     {
                 //         "data":[
                 //             {
                 //                 "tradeId":"5685030251",
                 //                 "orderId":"9669168142",
                 //                 "price":"11821.8",
                 //                 "action":"SELL",
                 //                 "baseAmount":"0.01",
                 //                 "quoteAmount":"118.218",
                 //                 "fee":"0.236436",
                 //                 "feeSymbol":"BNB",
                 //                 "isTaker":true,
                 //                 "timestamp":1644905714862,
                 //                 "createdTimestamp":1644905714862
                 //             }
                 //         ]
                 //     }
                 //
                 return this->parseTrades(trades, market, since, limit);
               })
        .share();
  }

  virtual std::any parseTransactionStatus(std::any status) {
    std::any states = ccxt::dict{
        {std::string("COMPLETE"), std::string("ok")},
        {std::string("INVALID"), std::string("failed")},
        {std::string("PROCESSING"), std::string("pending")},
        {std::string("WAIT_PROCESS"), std::string("pending")},
        {std::string("FAILED"), std::string("failed")},
        {std::string("EXPIRED"), std::string("failed")},
        {std::string("CANCELLED"), std::string("failed")},
        {std::string("EMAIL_VERIFICATION"), std::string("pending")},
        {std::string("WAIT_CONFIRMATION"), std::string("pending")},
    };
    return this->safeString(states, status, status);
  }

  std::any parseTransaction(std::any transaction,
                            std::any currency = std::any{}) override {
    //
    // fetchDeposits
    //
    //    {
    //        "serial": "20220214X766799",
    //        "timestamp": "1644833015053",
    //        "address": "bnb1xml62k5a9dcewgc542fha75fyxdcp0zv8eqfsh",
    //        "amount": "0.20000000",
    //        "fee": "0.00000000",
    //        "total": "0.20000000",
    //        "status": "COMPLETE",
    //        "txid":
    //        "A3CC4F6828CC752B9F3737F48B5826B9EC2857040CB5141D0CC955F7E53DB6D9",
    //        "message": "778553959",
    //        "protocol": "MAIN",
    //        "id": "2905906537"
    //    }
    //
    // fetchWithdrawals || fetchWithdraw
    //
    //    {
    //        "serial": "20220215BW14069838",
    //        "timestamp": "1644907716044",
    //        "address": "TKrwMaZaGiAvtXCFT41xHuusNcs4LPWS7w",
    //        "amount": "8.00000000",
    //        "fee": "2.00000000",
    //        "total": "10.00000000",
    //        "status": "COMPLETE",
    //        "txid":
    //        "50bf250c71a582f40cf699fb58bab978437ea9bdf7259ff8072e669aab30c32b",
    //        "protocol": "TRX",
    //        "id": "9925310345"
    //    }
    //
    // withdraw
    //
    //    {
    //        "serial": "20220215BW14069838",
    //        "currency": "USDT",
    //        "protocol": "TRX",
    //        "address": "TKrwMaZaGiAvtXCFT41xHuusNcs4LPWS7w",
    //        "amount": "8",
    //        "fee": "2",
    //        "total": "10"
    //    }
    //
    std::any currencyId = this->safeString(transaction, std::string("coin"));
    std::any code = this->safeCurrencyCode(currencyId, currency);
    std::any timestamp =
        this->safeInteger(transaction, std::string("timestamp"));
    std::any address = this->safeString(transaction, std::string("address"));
    std::any tag = this->safeString(transaction, std::string("message"));
    std::any status = this->safeString(transaction, std::string("status"));
    std::any networkId = this->safeString(transaction, std::string("protocol"));
    if (isTrue(isEqual(networkId, std::string("MAIN")))) {
      networkId = code;
    }
    return ccxt::dict{
        {std::string("info"), transaction},
        {std::string("id"),
         this->safeString(transaction, std::string("serial"))},
        {std::string("txid"),
         this->safeString(transaction, std::string("txid"))},
        {std::string("type"), std::any{}},
        {std::string("currency"), code},
        {std::string("network"), this->networkIdToCode(networkId, code)},
        {std::string("amount"),
         this->safeNumber(transaction, std::string("total"))},
        {std::string("status"), this->parseTransactionStatus(status)},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("address"), address},
        {std::string("addressFrom"), std::any{}},
        {std::string("addressTo"), address},
        {std::string("tag"), tag},
        {std::string("tagFrom"), std::any{}},
        {std::string("tagTo"), tag},
        {std::string("updated"), std::any{}},
        {std::string("comment"), std::any{}},
        {std::string("internal"), std::any{}},
        {std::string("fee"),
         ccxt::dict{
             {std::string("currency"), code},
             {std::string("cost"),
              this->safeNumber(transaction, std::string("fee"))},
             {std::string("rate"), std::any{}},
         }},
    };
  }

  /**
   * @method
   * @name bitopro#fetchDeposits
   * @description fetch all deposits made to an account
   * @see
   * https://github.com/bitoex/bitopro-offical-api-docs/blob/master/api/v3/private/get_deposit_invoices_data.md
   * @param {string} code unified currency code
   * @param {int} [since] the earliest time in ms to fetch deposits for
   * @param {int} [limit] the maximum number of deposits structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [transaction structures]{@link
   * https://docs.ccxt.com/?id=transaction-structure}
   */
  std::shared_future<std::any>
  fetchDeposits(std::any code = std::any{}, std::any since = std::any{},
                std::any limit = std::any{},
                std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(code, std::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(
                           " fetchDeposits() requires the code argument"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any currency = this->safeCurrency(code);
                 std::any request = ccxt::dict{
                     {std::string("currency"),
                      ::getValue(currency, std::string("id"))},
                 };
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("startTimestamp"), since);
                 }
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 std::any response =
                     awaitValue(this->privateGetWalletDepositHistoryCurrency(
                         this->extend(request, params)));
                 std::any result = this->safeList(response, std::string("data"),
                                                  ccxt::list{});
                 //
                 //     {
                 //         "data":[
                 //             {
                 //                 "serial":"20220214X766799",
                 //                 "timestamp":"1644833015053",
                 //                 "address":"bnb1xml62k5a9dcewgc542fha75fyxdcp0zv8eqfsh",
                 //                 "amount":"0.20000000",
                 //                 "fee":"0.00000000",
                 //                 "total":"0.20000000",
                 //                 "status":"COMPLETE",
                 //                 "txid":"A3CC4F6828CC752B9F3737F48B5826B9EC2857040CB5141D0CC955F7E53DB6D9",
                 //                 "message":"778553959",
                 //                 "protocol":"MAIN",
                 //                 "id":"2905906537"
                 //             }
                 //         ]
                 //     }
                 //
                 return this->parseTransactions(
                     result, currency, since, limit,
                     ccxt::dict{
                         {std::string("type"), std::string("deposit")},
                     });
               })
        .share();
  }

