  std::any sign(std::any path, std::any api = std::string("public"),
                std::any method = std::string("GET"),
                std::any params = ccxt::dict{}, std::any headers = std::any{},
                std::any body = std::any{}) override {
    std::any url = add(std::string("/"), this->implodeParams(path, params));
    std::any query = this->omit(params, this->extractParams(path));
    if (isTrue(isEqual(headers, std::any{}))) {
      headers = ccxt::dict{};
    }
    ::setValue(headers, std::string("X-BITOPRO-API"), std::string("ccxt"));
    if (isTrue(isEqual(api, std::string("private")))) {
      this->checkRequiredCredentials();
      if (isTrue(isTrue(isEqual(method, std::string("POST"))) ||
                 isTrue(isEqual(method, std::string("PUT"))))) {
        body = this->json(params);
        std::any payload = this->stringToBase64(body);
        std::any signature = this->hmac(this->encode(payload),
                                        this->encode(this->secret), sha384);
        ::setValue(headers, std::string("X-BITOPRO-APIKEY"), this->apiKey);
        ::setValue(headers, std::string("X-BITOPRO-PAYLOAD"), payload);
        ::setValue(headers, std::string("X-BITOPRO-SIGNATURE"), signature);
      } else if (isTrue(isTrue(isEqual(method, std::string("GET"))) ||
                        isTrue(isEqual(method, std::string("DELETE"))))) {
        if (isTrue(isGreaterThan(getArrayLength(getObjectKeys(query)), 0))) {
          url = add(url, add(std::string("?"), this->urlencode(query)));
        }
        std::any nonce = this->milliseconds();
        std::any rawData = ccxt::dict{
            {std::string("nonce"), nonce},
        };
        std::any data = this->json(rawData);
        std::any payload = this->stringToBase64(data);
        std::any signature = this->hmac(this->encode(payload),
                                        this->encode(this->secret), sha384);
        ::setValue(headers, std::string("X-BITOPRO-APIKEY"), this->apiKey);
        ::setValue(headers, std::string("X-BITOPRO-PAYLOAD"), payload);
        ::setValue(headers, std::string("X-BITOPRO-SIGNATURE"), signature);
      }
    } else if (isTrue(isTrue(isEqual(api, std::string("public"))) &&
                      isTrue(isEqual(method, std::string("GET"))))) {
      if (isTrue(isGreaterThan(getArrayLength(getObjectKeys(query)), 0))) {
        url = add(url, add(std::string("?"), this->urlencode(query)));
      }
    }
    url = add(::getValue(::getValue(this->urls, std::string("api")),
                         std::string("rest")),
              url);
    return ccxt::dict{
        {std::string("url"), url},
        {std::string("method"), method},
        {std::string("body"), body},
        {std::string("headers"), headers},
    };
  }

  std::any handleErrors(std::any code, std::any reason, std::any url,
                        std::any method, std::any headers, std::any body,
                        std::any response, std::any requestHeaders,
                        std::any requestBody) override {
    if (isTrue(isEqual(response, std::any{}))) {
      return std::any{}; // fallback to the default error handler
    }
    if (isTrue(isTrue(isGreaterThanOrEqual(code, 200)) &&
               isTrue(isLessThan(code, 300)))) {
      return std::any{};
    }
    std::any feedback = add(add(this->id, std::string(" ")), body);
    std::any error = this->safeString(response, std::string("error"));
    this->throwExactlyMatchedException(
        ::getValue(this->exceptions, std::string("exact")), error, feedback);
    this->throwBroadlyMatchedException(
        ::getValue(this->exceptions, std::string("broad")), error, feedback);
    throw ExchangeError(toString(feedback));
  }
